@@ -6,17 +6,30 @@ namespace clinic {

 struct Owner;

 struct Pet {
     std::string name;
-    std::shared_ptr<Owner> owner;
+    std::shared_ptr<Owner> owner;
+    int visits = 0;
 };

 struct Owner {
     std::string last_name;
-    std::vector<std::string> pet_names;
+    std::vector<std::shared_ptr<Pet>> pets;
 };

+inline void Link(const std::shared_ptr<Owner>& owner, const std::shared_ptr<Pet>& pet) {
+    pet->owner = owner;
+    owner->pets.push_back(pet);
+}
+
+inline int TotalVisits(const Owner& owner) {
+    int total = 0;
+    for (const auto& pet : owner.pets) {
+        total += pet->visits;
+    }
+    return total;
+}
+
 }  // namespace clinic
